export const secureReviewExercises: Exercise[] = [
  {"id":"scr-injection-sql-dans-order-by","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Injection SQL dans ORDER BY","company":"CWE-89 ; PortSwigger Web Security Academy — SQL injection in ORDER BY clause","language":"python","code":"def get_products(sort_by, order):\n    conn = get_db()\n    cur = conn.cursor()\n    query = f\"SELECT id, name, price FROM products WHERE active = %s ORDER BY {sort_by} {order}\"\n    cur.execute(query, (True,))\n    return cur.fetchall()","question":"Cet endpoint de listing paramètre correctement la valeur du WHERE. Quelle est la vulnérabilité réelle ?","options":["sort_by et order sont concaténés dans la requête : injection SQL via la clause ORDER BY, non couverte par les paramètres liés","le paramètre lié %s ne peut pas recevoir un booléen, ce qui force une réécriture non sûre de la requête","active = %s permet une injection booléenne aveugle car la comparaison est évaluée côté serveur","fetchall charge tout le jeu en mémoire : seule une pagination évite le déni de service exploitable"],"answer":0,"explanation":"Les placeholders paramétrés (%s) ne s'appliquent qu'aux VALEURS, jamais aux identifiants (noms de colonnes) ni aux mots-clés SQL (ASC/DESC). Ici sort_by et order sont interpolés en clair : un attaquant fournit par ex. order = \"(CASE WHEN (SELECT ...) THEN name ELSE price END)\" pour une injection aveugle basée sur ORDER BY. La bonne pratique est une allowlist stricte de colonnes/directions. Les distracteurs sont faux : les booléens se bindent parfaitement (option 2) ; active=%s est correctement paramétré donc pas injectable (option 3) ; fetchall est un souci de perf, pas la faille de sécurité (option 4).","tags":["sql-injection","order-by","python","allowlist"]},
  {"id":"scr-injection-de-commande-via-exec","type":"find-error","domain":"software","topic":"secure-review","difficulty":"intermediate","title":"Injection de commande via exec","company":"CWE-78 ; OWASP Code Review Guide — OS Command Injection","language":"javascript","code":"const { exec } = require('child_process');\napp.get('/ping', (req, res) => {\n  const host = req.query.host;\n  exec(`ping -c 4 ${host}`, (err, stdout) => {\n    if (err) return res.status(500).send('error');\n    res.type('text/plain').send(stdout);\n  });\n});","question":"Ce handler Express exécute un ping. Où est la faille exploitable ?","options":["host est concaténé dans exec qui passe par /bin/sh : injection de commande via ;, $(...) ou backticks","stdout renvoyé sans échappement HTML : XSS réfléchi si la sortie contient du balisage","utiliser GET pour une action serveur expose l'endpoint à une attaque CSRF non authentifiée","exec est asynchrone : une condition de course sur res permet de répondre deux fois au client"],"answer":0,"explanation":"child_process.exec exécute la chaîne via un shell (/bin/sh -c), donc tout métacaractère shell dans host est interprété : `host=8.8.8.8; cat /etc/passwd` ou `$(reboot)` s'exécute. Il faut execFile('ping', ['-c','4', host]) qui ne passe pas par un shell, avec validation du format. Le contenu est renvoyé en text/plain donc pas de XSS (option 2). CSRF (option 3) ne s'applique pas à une simple lecture idempotente et n'est pas LA faille. exec ne crée pas de double réponse ici (option 4).","tags":["command-injection","nodejs","exec","shell"]},
  {"id":"scr-telechargement-et-path-traversal","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Téléchargement et path traversal","company":"CWE-22 ; OWASP ASVS v4 §12.3 File Execution","language":"java","code":"@GetMapping(\"/download\")\npublic ResponseEntity<byte[]> download(@RequestParam String file) throws IOException {\n    File base = new File(\"/var/app/files\");\n    File target = new File(base, file);\n    byte[] data = Files.readAllBytes(target.toPath());\n    return ResponseEntity.ok(data);\n}","question":"Ce contrôleur Spring sert des fichiers. Quelle est la vulnérabilité ?","options":["file peut contenir ../ : path traversal, il manque une vérification target.getCanonicalPath().startsWith(base canonique)","new File(base, file) résout un chemin relatif au CWD du processus et non à base, contournant le répertoire","readAllBytes charge tout le fichier en mémoire : un gros fichier provoque un déni de service par OOM","la réponse n'a pas de Content-Type : le navigateur peut interpréter le contenu et déclencher un XSS"],"answer":0,"explanation":"new File(base, file) traite bien file comme relatif à base, MAIS un file = \"../../etc/passwd\" remonte l'arborescence : path traversal classique. La défense est de canoniser (getCanonicalPath) et vérifier que le résultat commence toujours par le répertoire de base canonisé, ou d'utiliser une allowlist d'identifiants. L'option 2 est fausse : le second argument est bien résolu relativement à base. L'OOM (option 3) est un souci de robustesse. L'absence de Content-Type (option 4) est une mauvaise pratique mais pas la faille centrale de traversal.","tags":["path-traversal","java","spring","canonicalization"]},
  {"id":"scr-confusion-d-algorithme-jwt","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Confusion d'algorithme JWT","company":"CWE-347 ; Auth0 — Critical vulnerabilities in JSON Web Token libraries (algorithm confusion RS256/HS256)","language":"python","code":"import jwt\n\ndef verify(token, public_key):\n    return jwt.decode(\n        token,\n        public_key,\n        algorithms=[\"RS256\", \"HS256\"],\n    )","question":"Cette fonction vérifie un JWT signé en RS256. Pourquoi est-elle vulnérable ?","options":["accepter RS256 et HS256 avec la clé publique permet la confusion d'algorithme : l'attaquant forge un HS256 signé avec la clé publique connue","la clé publique ne devrait jamais servir à décoder un JWT, seule la clé privée peut vérifier une signature RS256","l'absence de paramètre audience/issuer laisse rejouer un token émis pour un autre service tiers","jwt.decode ne vérifie pas l'expiration par défaut, ce qui laisse un token révoqué rester valide"],"answer":0,"explanation":"En listant HS256 en plus de RS256, la même clé (la clé PUBLIQUE, non secrète) sert de secret HMAC. L'attaquant récupère la clé publique, forge un jeton avec header alg=HS256 signé en HMAC par cette clé publique ; la bibliothèque, voyant HS256, valide avec public_key et accepte le token forgé. Il faut restreindre algorithms à [\"RS256\"] uniquement. La vérification par clé publique est justement le fonctionnement normal de RS256 (option 2 fausse). aud/iss (option 3) est une défense en profondeur mais pas la faille. PyJWT vérifie exp par défaut (option 4 fausse).","tags":["jwt","algorithm-confusion","rs256","authentication"]},
  {"id":"scr-parsing-xml-et-xxe","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Parsing XML et XXE","company":"CWE-611 ; OWASP XXE Prevention Cheat Sheet","language":"java","code":"DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();\nDocumentBuilder db = dbf.newDocumentBuilder();\nDocument doc = db.parse(new InputSource(new StringReader(xml)));\nreturn doc.getDocumentElement().getTextContent();","question":"Ce code parse un document XML fourni par le client. Quel est le problème ?","options":["la factory ne désactive pas les DTD/entités externes (disallow-doctype-decl) : XXE, lecture de fichiers et SSRF","StringReader n'impose pas l'encodage : un BOM UTF-16 malformé peut provoquer une injection de contenu","DocumentBuilder n'est pas thread-safe : un accès concurrent corrompt le DOM et fuite des données","parse devrait activer le mode validant pour rejeter les documents malformés avant traitement"],"answer":0,"explanation":"DocumentBuilderFactory autorise par défaut le traitement des DTD et des entités externes. Un XML contenant `<!DOCTYPE x [<!ENTITY e SYSTEM \"file:///etc/passwd\">]>` puis `&e;` exfiltre des fichiers (ou déclenche un SSRF via une URL http). Il faut dbf.setFeature(\"http://apache.org/xml/features/disallow-doctype-decl\", true) (ou désactiver external-general/parameter-entities). Le mode validant (option 4) AGGRAVERAIT en résolvant la DTD. L'encodage (option 2) et le thread-safety (option 3) sont réels mais ne sont pas la vulnérabilité XXE.","tags":["xxe","java","xml","ssrf"]},
  {"id":"scr-proxy-de-recuperation-d-url","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Proxy de récupération d'URL","company":"CWE-918 ; OWASP SSRF Prevention Cheat Sheet","language":"go","code":"func fetch(w http.ResponseWriter, r *http.Request) {\n    target := r.URL.Query().Get(\"url\")\n    resp, err := http.Get(target)\n    if err != nil {\n        http.Error(w, \"bad\", 502)\n        return\n    }\n    defer resp.Body.Close()\n    io.Copy(w, resp.Body)\n}","question":"Ce handler récupère une URL fournie par l'utilisateur. Quelle est la faille de sécurité principale ?","options":["url est contrôlée par le client et passée à http.Get : SSRF vers des cibles internes (169.254.169.254, localhost, réseau privé)","resp.Body n'est fermé qu'en cas de succès : une fuite de descripteurs finit par épuiser les sockets","io.Copy sans limite de taille permet à une réponse volumineuse de saturer la mémoire du serveur","aucun timeout n'est configuré sur le client HTTP : une cible lente bloque durablement le goroutine"],"answer":0,"explanation":"L'URL est entièrement contrôlée par l'attaquant : c'est un SSRF. Il peut atteindre http://169.254.169.254/latest/meta-data/ (credentials cloud), http://localhost:port (services d'admin internes) ou scanner le réseau privé. La défense : allowlist de domaines, résolution DNS + refus des plages privées/link-local, désactivation des redirections, schémas restreints. Les options 2, 3 et 4 décrivent de vrais défauts de robustesse (fuite, DoS, timeout) mais ne sont pas la vulnérabilité SSRF demandée ; d'ailleurs resp.Body est bien fermé via defer après le check d'erreur.","tags":["ssrf","go","http-client","cloud-metadata"]},
  {"id":"scr-template-flask-et-ssti","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Template Flask et SSTI","company":"CWE-1336 ; PortSwigger — Server-side template injection (Jinja2)","language":"python","code":"from flask import request, render_template_string\n\n@app.route('/hello')\ndef hello():\n    name = request.args.get('name', 'World')\n    template = f\"<h1>Hello {name}</h1>\"\n    return render_template_string(template)","question":"Cette route affiche un message de bienvenue. Où est la vulnérabilité ?","options":["name est interpolé dans la chaîne rendue par render_template_string : SSTI Jinja2 ({{7*7}}, __class__) jusqu'au RCE","le contexte HTML de name n'est pas échappé : XSS réfléchi limité à l'exécution de script côté client","render_template_string désactive l'autoescape : les balises HTML injectées provoquent un défaçage","la f-string évalue name au moment du formatage, ce qui expose les variables locales de la fonction"],"answer":0,"explanation":"L'entrée utilisateur est concaténée dans la CHAINE de template puis passée à render_template_string : Jinja2 évalue alors {{...}} présent dans name. Un attaquant fournit name={{7*7}} (renvoie 49) puis remonte via {{''.__class__.__mro__[1].__subclasses__()}} jusqu'à l'exécution de commandes (RCE). C'est un SSTI, strictement plus grave qu'un simple XSS (option 2) car il s'exécute côté serveur. Il faut passer les données comme variable de contexte (render_template_string(\"<h1>Hello {{name}}</h1>\", name=name)), jamais dans le template lui-même. L'autoescape Jinja est actif par défaut (option 3). Option 4 : la f-string n'exécute pas de code utilisateur, c'est Jinja qui le fait.","tags":["ssti","jinja2","flask","rce"]},
  {"id":"scr-xss-base-sur-le-dom","type":"find-error","domain":"software","topic":"secure-review","difficulty":"intermediate","title":"XSS basé sur le DOM","company":"CWE-79 ; PortSwigger — DOM-based XSS (source location.search, sink innerHTML)","language":"javascript","code":"const params = new URLSearchParams(location.search);\nconst user = params.get('user');\ndocument.getElementById('welcome').innerHTML = 'Bienvenue ' + user;","question":"Ce script personnalise un message d'accueil. Quelle est la vulnérabilité ?","options":["user va d'une source (location.search) vers innerHTML sans échappement : XSS DOM via <img src=x onerror=...>","URLSearchParams ne décode pas les caractères pourcentés, laissant passer des séquences d'échappement dangereuses","innerHTML neutralise les balises <script> injectées, la faille se limite donc à une injection de style CSS","getElementById renvoie null si l'élément manque, ce qui déclenche une erreur exploitable en déni de service"],"answer":0,"explanation":"Le motif source→sink caractéristique du XSS DOM : la valeur user (source: location.search) atteint innerHTML (sink dangereux) sans assainissement. Les balises <script> insérées via innerHTML ne s'exécutent effectivement pas (option 3 est un piège classique), MAIS <img src=x onerror=alert(1)> ou <svg onload=...> s'exécutent parfaitement — donc XSS bien réel. Utiliser textContent, ou une sanitization (DOMPurify) et un encodage contextuel. URLSearchParams décode bien les %xx (option 2 fausse). L'option 4 décrit une erreur JS, pas la faille XSS.","tags":["xss","dom-xss","innerhtml","javascript"]},
  {"id":"scr-acces-direct-a-une-ressource-par-id","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Accès direct à une ressource par ID","company":"CWE-639 ; OWASP API Security Top 10 — API1:2023 Broken Object Level Authorization","language":"javascript","code":"app.get('/api/invoices/:id', authenticate, async (req, res) => {\n  const invoice = await Invoice.findByPk(req.params.id);\n  if (!invoice) return res.status(404).end();\n  res.json(invoice);\n});","question":"Cet endpoint renvoie une facture. Quelle est la faille de contrôle d'accès ?","options":["aucune vérification que la facture appartient à req.user : IDOR/BOLA, tout id valide est lisible par n'importe quel compte","req.params.id est concaténé dans findByPk, ce qui ouvre une injection SQL par manipulation de l'identifiant","le middleware authenticate s'exécute après la résolution de la route, laissant passer les requêtes anonymes","renvoyer 404 pour une facture inexistante révèle par timing les identifiants réellement présents en base"],"answer":0,"explanation":"L'utilisateur est authentifié (authenticate) mais l'AUTORISATION au niveau objet manque : rien ne vérifie que invoice.ownerId === req.user.id. Un attaquant itère les :id (souvent séquentiels) et lit les factures d'autrui — c'est du BOLA/IDOR, la faille n°1 des API. Corriger avec un filtre sur le propriétaire : findOne({ where: { id, userId: req.user.id } }). findByPk utilise un binding paramétré donc pas d'injection (option 2). Les middlewares Express s'exécutent dans l'ordre déclaré, donc authenticate d'abord (option 3). Le 404 n'est pas la faille centrale (option 4).","tags":["idor","bola","access-control","authorization"]},
  {"id":"scr-creation-d-utilisateur-et-mass-assignmen","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Création d'utilisateur et mass assignment","company":"CWE-915 ; OWASP API Security Top 10 — API6:2023 Mass Assignment","language":"javascript","code":"app.post('/users', async (req, res) => {\n  const user = await User.create(req.body);\n  res.json(user);\n});","question":"Cette route crée un utilisateur avec Sequelize. Quelle est la vulnérabilité ?","options":["User.create(req.body) affecte tous les champs du corps : mass assignment, l'attaquant fixe role='admin' ou isVerified=true","req.body n'est pas validé : une injection SQL est possible via les valeurs textuelles des attributs","la création n'est pas encapsulée dans une transaction, laissant un utilisateur partiellement enregistré","res.json sérialise l'objet complet, exposant le hash de mot de passe généré côté serveur à l'appelant"],"answer":0,"explanation":"Passer req.body entier à create lie aveuglément toutes les colonnes du modèle, y compris des champs sensibles non prévus (role, isAdmin, isVerified, balance). L'attaquant ajoute {\"role\":\"admin\"} et s'auto-promeut. Défense : allowlist explicite via l'option fields de Sequelize (User.create(req.body, { fields: ['email','name','password'] })) ou un DTO. Sequelize paramètre les valeurs donc pas d'injection SQL (option 2). L'absence de transaction (option 3) et la fuite du hash dans la réponse (option 4) sont de vrais défauts secondaires mais pas la faille de mass assignment.","tags":["mass-assignment","sequelize","privilege-escalation","api-security"]},
  {"id":"scr-chiffrement-aes-par-defaut","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Chiffrement AES par défaut","company":"CWE-327 ; OWASP Cryptographic Storage Cheat Sheet","language":"java","code":"Cipher cipher = Cipher.getInstance(\"AES\");\ncipher.init(Cipher.ENCRYPT_MODE, key);\nbyte[] ct = cipher.doFinal(plaintext);","question":"Ce code chiffre des données avec AES. Quel est le défaut cryptographique ?","options":["\"AES\" se résout en AES/ECB/PKCS5Padding : mode ECB déterministe qui révèle les motifs répétés du clair","aucun IV n'est fourni, donc l'initialisation en CBC échoue silencieusement et retombe sur du clair non chiffré","la longueur de la clé n'est pas vérifiée : une clé de 64 bits est acceptée et affaiblit tout le chiffrement","doFinal n'est pas thread-safe : un appel concurrent mélange les blocs et corrompt le texte chiffré"],"answer":0,"explanation":"En Java, getInstance(\"AES\") sans mode/padding utilise le défaut du provider : AES/ECB/PKCS5Padding. ECB chiffre chaque bloc indépendamment, donc deux blocs de clair identiques donnent le même chiffré — les motifs restent visibles (l'exemple du « pingouin ECB »). Il faut un mode authentifié : AES/GCM/NoPadding avec un IV/nonce unique. Ce n'est PAS du CBC (option 2), justement parce que le défaut est ECB qui n'exige pas d'IV. La taille de clé (option 3) et le thread-safety (option 4) sont réels mais ne sont pas le défaut de mode ici.","tags":["cryptography","ecb","aes","java"]},
  {"id":"scr-iv-statique-en-cbc","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"IV statique en CBC","company":"CWE-329 ; NIST SP 800-38A Appendix C (IV requirements)","language":"python","code":"from Crypto.Cipher import AES\nfrom Crypto.Util.Padding import pad\n\nkey = load_key()\n\ndef encrypt(pt: bytes) -> bytes:\n    iv = b'\\x00' * 16\n    cipher = AES.new(key, AES.MODE_CBC, iv)\n    return cipher.encrypt(pad(pt, 16))","question":"Cette fonction chiffre en AES-CBC. Quel est le défaut ?","options":["l'IV est fixe (nul) et réutilisé : deux clairs à préfixe commun produisent le même chiffré, fuite d'information","pad avec un bloc de 16 est incorrect car CBC exige que le clair soit un multiple exact sans remplissage","MODE_CBC est intrinsèquement cassé et doit toujours être remplacé par MODE_GCM pour être sûr","la clé globale chargée une seule fois n'est jamais renouvelée, ce qui expose l'ensemble des messages"],"answer":0,"explanation":"En CBC, l'IV doit être imprévisible et unique par message. Un IV constant (ici nul) réutilisé fait que des messages partageant le même préfixe de blocs produisent des chiffrés identiques sur ces blocs — un attaquant détecte l'égalité/les motifs et monte des attaques (chosen-plaintext, BEAST-like). Il faut générer un IV aléatoire (get_random_bytes(16)) par chiffrement et le préfixer au chiffré. pad(..., 16) est correct (option 2 fausse). CBC bien utilisé n'est pas « cassé » (option 3, quoique GCM soit préférable car authentifié). Le renouvellement de clé (option 4) est un sujet distinct.","tags":["cryptography","iv-reuse","cbc","python"]},
  {"id":"scr-comparaison-de-secret-non-constante","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Comparaison de secret non constante","company":"CWE-208 ; OWASP ASVS v4 §2.9 / hmac.compare_digest","language":"python","code":"def check_token(provided: str) -> bool:\n    expected = get_api_token()\n    if provided == expected:\n        return True\n    return False","question":"Cette fonction valide un token d'API. Quel est le risque ?","options":["== s'arrête au premier octet différent : comparaison non constante exploitable par attaque temporelle, préférer hmac.compare_digest","== compare l'identité des objets str et non leur contenu, ce qui rejette parfois un token pourtant valide","le token en clair devrait être comparé sous forme hachée pour éviter sa lecture en mémoire par un attaquant","l'absence de limitation de débit permet un bruteforce en ligne, seule contre-mesure réellement efficace ici"],"answer":0,"explanation":"L'opérateur == sur des chaînes court-circuite dès le premier octet divergent : le temps d'exécution dépend du nombre d'octets corrects en préfixe. Un attaquant mesure ces micro-différences pour reconstruire le token octet par octet (attaque temporelle, praticable notamment en réseau local ou via amplification statistique). Il faut hmac.compare_digest, à temps constant. En Python == compare bien le CONTENU des str, pas l'identité (option 2 fausse). Hacher (option 3) et limiter le débit (option 4) sont utiles mais ne corrigent pas la fuite temporelle de la comparaison elle-même.","tags":["timing-attack","constant-time","python","authentication"]},
  {"id":"scr-stockage-de-mot-de-passe","type":"find-error","domain":"software","topic":"secure-review","difficulty":"intermediate","title":"Stockage de mot de passe","company":"CWE-916 ; OWASP Password Storage Cheat Sheet","language":"php","code":"function store_password($pw) {\n    global $db;\n    $hash = md5($pw);\n    $uid = (int) $_SESSION['uid'];\n    $db->query(\"UPDATE users SET pw = '$hash' WHERE id = $uid\");\n}","question":"Cette fonction enregistre le mot de passe d'un utilisateur. Quel est le défaut de sécurité principal ?","options":["md5 est un hash rapide et sans sel : cassable par rainbow tables et bruteforce GPU, utiliser password_hash (bcrypt/argon2)","les collisions connues de md5 permettent à deux mots de passe distincts de produire le même hash accepté","$hash est concaténé dans la requête : une injection SQL est possible via un mot de passe contenant une apostrophe","$_SESSION['uid'] provient du client et permet à un utilisateur de modifier le mot de passe d'un autre compte"],"answer":0,"explanation":"md5 est conçu pour la vitesse, sans sel ni facteur de coût : des milliards de tentatives/seconde sur GPU et des tables arc-en-ciel toutes prêtes rendent le crackage trivial. Il faut password_hash($pw, PASSWORD_ARGON2ID) (ou bcrypt) qui intègre sel et coût réglable, et password_verify pour la vérification. La faiblesse par collision (option 2) n'est pas le problème pour le stockage de secret. $hash est un hex md5, donc pas d'apostrophe injectable (option 3), et $uid est casté en int et lu côté serveur en session (option 4), donc non contrôlable directement par le client.","tags":["password-hashing","md5","php","bcrypt"]},
  {"id":"scr-deserialisation-d-un-cookie","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Désérialisation d'un cookie","company":"CWE-502 ; OWASP — PHP Object Injection / Deserialization Cheat Sheet","language":"php","code":"$prefs = unserialize($_COOKIE['prefs']);\n$theme = $prefs['theme'] ?? 'light';\napply_theme($theme);","question":"Ce code restaure les préférences depuis un cookie. Quelle est la vulnérabilité ?","options":["unserialize sur une entrée utilisateur permet l'injection d'objet PHP : une POP chain via __wakeup/__destruct mène au RCE","unserialize renvoie false en cas d'erreur : un cookie malformé retombe silencieusement sur des préférences vides","json_decode serait plus performant : la sérialisation PHP native est plus lente et gonfle la taille du cookie","le cookie n'est pas signé : l'attaquant peut seulement falsifier le thème affiché, sans impact plus large"],"answer":0,"explanation":"unserialize sur des données contrôlées par l'attaquant instancie des objets arbitraires ; si une classe chargée définit des méthodes magiques (__wakeup, __destruct, __toString...), on chaîne des « gadgets » (POP chain) pour atteindre l'exécution de code, la lecture/écriture de fichiers, etc. La règle : ne jamais unserialize une entrée non fiable ; utiliser json_decode, ou passer allowed_classes=>false. false en cas d'erreur (option 2) et la perf (option 3) n'abordent pas la faille. Le risque dépasse largement la falsification du thème (option 4) : c'est potentiellement un RCE.","tags":["deserialization","php","object-injection","rce"]},
  {"id":"scr-validation-par-expression-reguliere","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Validation par expression régulière","company":"CWE-1333 ; OWASP — Regular Expression Denial of Service (ReDoS)","language":"javascript","code":"const re = /^(\\w+\\s?)*$/;\n\nfunction validate(input) {\n  return re.test(input);\n}","question":"Cette regex valide un identifiant. Quel est le risque de sécurité ?","options":["(\\w+\\s?)* imbrique des quantificateurs : backtracking catastrophique (ReDoS) sur une longue entrée non appariante","\\w ne couvre pas les caractères Unicode : des identifiants internationaux valides sont rejetés à tort","test() est stateful avec le drapeau global : des appels successifs renvoient un résultat incohérent","les ancres ^ et $ manquent en mode multiligne, laissant passer une entrée contenant des sauts de ligne"],"answer":0,"explanation":"Le motif (\\w+\\s?)* superpose deux quantificateurs sur des classes qui se chevauchent : pour une entrée comme \"aaaa...!\" (longue suite de \\w suivie d'un caractère non apparié), le moteur explore un nombre exponentiel de partitions avant d'échouer — c'est le backtracking catastrophique, un ReDoS qui gèle le thread (DoS). Réécrire en un motif linéaire (ex. /^\\w+(\\s\\w+)*$/ ou validation non-regex), ou utiliser un moteur RE2. \\w limité à l'ASCII (option 2) est un défaut fonctionnel, pas de sécurité. re n'a pas le flag g (option 3). Les ancres sont bien présentes (option 4).","tags":["redos","regex","dos","javascript"]},
  {"id":"scr-redirection-post-authentification","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Redirection post-authentification","company":"CWE-601 ; PortSwigger — Open redirection ; OWASP Unvalidated Redirects","language":"javascript","code":"app.get('/login/callback', (req, res) => {\n  handleAuth(req);\n  const next = req.query.next || '/';\n  res.redirect(next);\n});","question":"Après connexion, l'utilisateur est redirigé vers next. Quelle est la faille ?","options":["next n'est pas validé : open redirect via //evil.com ou https:evil.com, exploité pour du phishing crédible","res.redirect renvoie un 302 alors qu'un 301 permanent est requis pour ne pas rejouer l'authentification","la valeur par défaut '/' est relative : sur un sous-chemin, elle renvoie vers la racine et casse la navigation","next est réfléchi dans l'en-tête Location : sans encodeURIComponent, une injection d'en-tête HTTP est possible"],"answer":0,"explanation":"next est une URL contrôlée par l'attaquant, redirigée sans contrôle : un lien /login/callback?next=//evil.com (ou https://evil.com) envoie la victime, après une authentification légitime sur le vrai domaine, vers un site malveillant — phishing très convaincant, ou vol de token si un fragment/paramètre le porte. Défense : n'accepter que des chemins relatifs internes (rejeter les valeurs commençant par //, http:, https:, backslash) ou une allowlist. Le code HTTP (option 2) et la valeur par défaut (option 3) ne sont pas des failles. L'injection d'en-tête (option 4) est atténuée par les frameworks qui filtrent CR/LF ; la faille réelle est l'open redirect.","tags":["open-redirect","phishing","nodejs","input-validation"]},
  {"id":"scr-fusion-recursive-d-objets","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Fusion récursive d'objets","company":"CWE-1321 ; PortSwigger — Prototype pollution","language":"javascript","code":"function merge(target, source) {\n  for (const key in source) {\n    if (typeof source[key] === 'object' && source[key] !== null) {\n      target[key] = merge(target[key] || {}, source[key]);\n    } else {\n      target[key] = source[key];\n    }\n  }\n  return target;\n}","question":"Cette fonction fusionne deux objets. Quelle est la vulnérabilité ?","options":["aucun filtrage des clés __proto__/constructor/prototype : pollution de prototype affectant tous les objets de l'application","for...in parcourt aussi les propriétés héritées de source, ce qui copie par erreur des méthodes du prototype","la copie n'est pas profonde pour les tableaux : une référence partagée modifie involontairement l'objet source","target[key] || {} écrase une valeur falsy existante (0, '') par un objet, corrompant les données légitimes"],"answer":0,"explanation":"Si source (souvent issue d'un JSON.parse d'entrée utilisateur) contient la clé __proto__ (ou constructor.prototype), la branche récursive écrit sur Object.prototype : merge({}, JSON.parse('{\"__proto__\":{\"isAdmin\":true}}')) rend ({}).isAdmin === true pour TOUS les objets. Conséquences : contournement d'autorisation, DoS, voire RCE selon les gadgets. Défense : ignorer ces clés (if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue), Object.create(null), ou Map. Les options 2, 3 et 4 décrivent de vrais comportements/bugs de fusion mais aucun n'est la faille de pollution de prototype.","tags":["prototype-pollution","javascript","object-merge","deserialization"]},
  {"id":"scr-changement-d-email-sans-jeton","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Changement d'email sans jeton","company":"CWE-352 ; OWASP CSRF Prevention Cheat Sheet","language":"javascript","code":"app.post('/account/email', authenticate, async (req, res) => {\n  req.user.email = req.body.email;\n  await req.user.save();\n  res.redirect('/account');\n});","question":"Cet endpoint change l'email du compte. Quelle protection manque-t-il ?","options":["aucun jeton anti-CSRF ni vérification d'origine : avec un cookie de session, un site tiers force le changement d'email","req.body.email n'est pas validé par une regex, laissant enregistrer une adresse syntaxiquement invalide","la redirection après un POST rejoue la requête si l'utilisateur actualise, doublant l'écriture en base","l'email n'est pas repassé en minuscules avant sauvegarde, ce qui crée des doublons de comptes distincts"],"answer":0,"explanation":"L'action modifie un état sensible via POST en s'appuyant uniquement sur le cookie de session (authenticate). Sans jeton anti-CSRF, sans vérification d'Origin/Referer et sans cookie SameSite, un attaquant héberge un formulaire auto-soumis qui, chargé par une victime connectée, change son email (prise de contrôle du compte via reset ultérieur). Défenses : jeton CSRF synchronizer, SameSite=Lax/Strict, re-authentification pour les actions sensibles. La validation d'email (option 2), le pattern PRG (option 3) et la normalisation de casse (option 4) sont des considérations de qualité, pas la faille CSRF.","tags":["csrf","session","nodejs","account-takeover"]},
  {"id":"scr-connexion-et-session","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Connexion et session","company":"CWE-384 ; OWASP Session Management Cheat Sheet (session fixation)","language":"php","code":"session_start();\nif (check_credentials($_POST['user'], $_POST['pass'])) {\n    $_SESSION['user'] = $_POST['user'];\n    $_SESSION['auth'] = true;\n    header('Location: /dashboard');\n    exit;\n}","question":"Ce code authentifie l'utilisateur. Quelle vulnérabilité de session comporte-t-il ?","options":["absence de session_regenerate_id(true) après authentification : fixation de session, un ID pré-imposé reste valide après login","check_credentials compare probablement le mot de passe en clair, exposant les secrets en cas de fuite de base","header('Location') sans exit poursuit l'exécution du script et exécute du code réservé aux comptes valides","$_SESSION['auth'] booléen est falsifiable côté client car stocké dans le cookie plutôt que sur le serveur"],"answer":0,"explanation":"L'identifiant de session n'est pas régénéré à l'élévation de privilège (passage anonyme→authentifié). Un attaquant qui a fixé l'ID de session de la victime avant sa connexion (via un lien, une injection de cookie, etc.) conserve un ID désormais authentifié : c'est la fixation de session. Il faut session_regenerate_id(true) juste après la validation des identifiants. Le hachage (option 2) dépend de check_credentials, non montré. exit EST présent (option 3, piège). $_SESSION est stocké côté serveur, seul l'ID transite en cookie (option 4 fausse).","tags":["session-fixation","php","authentication","session-management"]},
  {"id":"scr-cle-hmac-faible-pour-les-jwt","type":"mcq","domain":"software","topic":"secure-review","difficulty":"senior","title":"Clé HMAC faible pour les JWT","company":"CWE-326 ; RFC 7518 §3.2 (HS256 key length) ; hashcat mode 16500","question":"Une API signe ses JWT en HS256 avec le secret 'app-secret-2021'. Quel est le risque principal et pourquoi ?","options":["Le secret à faible entropie peut être bruteforcé hors-ligne à partir d'un seul JWT capturé, permettant de forger n'importe quel jeton","HS256 étant symétrique, tout client possédant le token peut inverser la signature et retrouver directement le secret utilisé","Un secret court oblige la bibliothèque à basculer silencieusement en alg=none, désactivant toute vérification de signature","La courte longueur du secret limite le nombre de claims signables, provoquant une troncation exploitable du payload"],"answer":0,"explanation":"HS256 calcule HMAC-SHA256(secret, header.payload). La signature n'est PAS chiffrée : un attaquant qui capture un seul JWT valide lance un bruteforce/dictionnaire hors-ligne (hashcat) sur le secret. Un secret à faible entropie comme 'app-secret-2021' tombe en quelques secondes ; l'attaquant re-signe alors n'importe quel payload (ex. \"role\":\"admin\") et forge des jetons acceptés. RFC 7518 exige une clé d'au moins la taille de la sortie du hash (256 bits) et à forte entropie. HS256 ne « révèle » pas le secret (option 2) : HMAC est à sens unique. Un secret court ne bascule pas en none (option 3) et ne tronque pas les claims (option 4).","tags":["jwt","weak-key","hmac","brute-force"]},
  {"id":"scr-recherche-ldap","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Recherche LDAP","company":"CWE-90 ; OWASP LDAP Injection Prevention Cheat Sheet","language":"java","code":"String filter = \"(&(objectClass=person)(uid=\" + username + \"))\";\nNamingEnumeration<SearchResult> results =\n    ctx.search(\"ou=people,dc=corp,dc=com\", filter, controls);\nboolean found = results.hasMore();","question":"Ce code recherche un utilisateur dans l'annuaire. Quelle est la vulnérabilité ?","options":["username est concaténé dans le filtre : injection LDAP, ex. *)(uid=* contourne le filtre et énumère tous les comptes","la base de recherche ou=people est concaténée dynamiquement, autorisant un déplacement latéral dans l'annuaire","SearchControls n'est pas configuré en SUBTREE_SCOPE, donc la recherche échoue à trouver des utilisateurs valides","results.hasMore() n'itère pas réellement les résultats, ce qui provoque un contournement d'authentification par timing"],"answer":0,"explanation":"username est inséré tel quel dans le filtre LDAP. En fournissant *)(uid=* ou *)(|(uid=*, l'attaquant réécrit la logique du filtre : énumération de comptes, contournement d'authentification (ex. injecter une clause toujours vraie), voire lecture d'attributs sensibles. Défense : échapper les métacaractères LDAP (RFC 4515 : parenthèses, astérisque, antislash, NUL) ou utiliser une API paramétrée. La base ou=people est ici statique (option 2). Le scope (option 3) est un souci fonctionnel. hasMore()/timing (option 4) est inventé.","tags":["ldap-injection","java","authentication","input-validation"]},
  {"id":"scr-ecriture-de-fichier-verifiee","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Écriture de fichier vérifiée","company":"CWE-367 ; OWASP — Time-of-check Time-of-use (TOCTOU)","language":"python","code":"import os\n\nif os.access(path, os.W_OK):\n    with open(path, 'w') as f:\n        f.write(data)","question":"Ce code vérifie les droits avant d'écrire. Quelle est la faille de sécurité ?","options":["fenêtre TOCTOU entre os.access et open : le chemin peut être remplacé (symlink) entre la vérification et l'écriture","os.access teste les permissions de l'UID réel tandis que open utilise l'UID effectif, mode 'w' échouant en setuid","le mode 'w' tronque un fichier existant avant l'écriture, provoquant une perte de données non atteignable autrement","open sans encodage explicite écrit selon la locale du système, corrompant les octets de data en environnement non-UTF8"],"answer":0,"explanation":"Il y a un intervalle de temps entre la vérification (os.access) et l'usage (open) : c'est un TOCTOU. Un attaquant peut, dans cette fenêtre, remplacer path par un lien symbolique vers une cible privilégiée (ex. /etc/passwd) ; le check passe sur l'original, l'écriture frappe la cible. Il faut supprimer le check préalable et ouvrir directement avec les bons flags (open avec O_NOFOLLOW / os.open et gestion d'exceptions), en s'appuyant sur les permissions du FD ouvert. L'écart UID réel/effectif (option 2) est un vrai piège d'os.access mais décrit mal l'exploitation ; la troncation (option 3) et l'encodage (option 4) ne sont pas des failles de sécurité ici.","tags":["toctou","race-condition","python","symlink"]},
  {"id":"scr-client-s3-et-identifiants","type":"find-error","domain":"software","topic":"secure-review","difficulty":"intermediate","title":"Client S3 et identifiants","company":"CWE-798 ; OWASP ASVS v4 §2.10 ; CWE Top 25 (Hard-coded Credentials)","language":"python","code":"import boto3\n\nAWS_ACCESS_KEY = \"AKIAIOSFODNN7EXAMPLE\"\nAWS_SECRET_KEY = \"wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY\"\n\ns3 = boto3.client('s3',\n    aws_access_key_id=AWS_ACCESS_KEY,\n    aws_secret_access_key=AWS_SECRET_KEY)","question":"Ce module configure un client AWS. Quel est le problème de sécurité ?","options":["identifiants AWS codés en dur : exposés via le VCS et la décompilation, ils doivent venir d'un rôle IAM ou d'un coffre","la clé secrète contient un / non échappé, ce qui casse l'authentification de signature SigV4 des requêtes","boto3.client sans région explicite envoie les requêtes vers un endpoint par défaut hors du périmètre autorisé","stocker la clé dans une variable de module la conserve en mémoire vive, la rendant lisible par un core dump"],"answer":0,"explanation":"Des secrets en dur dans le code finissent dans l'historique Git (irréversible sans réécriture), dans les images de conteneurs, et sont extractibles par décompilation/inspection. Ils ne peuvent pas être tournés facilement et fuient largement. Bonne pratique : rôles IAM (instances/conteneurs), variables d'environnement injectées, ou un gestionnaire de secrets (AWS Secrets Manager, Vault). Le / dans la clé est normal et géré par le SDK (option 2). L'absence de région (option 3) est fonctionnelle. La lecture par core dump (option 4) est marginale comparée à l'exposition dans le code source.","tags":["hardcoded-secret","aws","credentials","secrets-management"]},
  {"id":"scr-affichage-de-commentaires","type":"find-error","domain":"software","topic":"secure-review","difficulty":"intermediate","title":"Affichage de commentaires","company":"CWE-79 ; OWASP XSS Prevention Cheat Sheet (Rule #1)","language":"php","code":"foreach ($comments as $c) {\n    echo \"<div class='comment'>\" . $c['body'] . \"</div>\";\n}","question":"Cette boucle affiche des commentaires stockés. Quelle est la vulnérabilité ?","options":["$c['body'] est affiché sans htmlspecialchars : XSS stocké, le script d'un commentaire s'exécute chez chaque visiteur","l'attribut class en apostrophes simples permet une injection de classe CSS modifiant l'apparence de la page","la concaténation dans echo est vulnérable à une injection SQL de second ordre via le contenu du commentaire","seule l'absence d'en-tête Content-Security-Policy rend l'application exploitable en pratique par un attaquant"],"answer":0,"explanation":"Le corps du commentaire, stocké puis rendu tel quel dans le HTML, n'est jamais encodé : un commentaire contenant <script>...</script> ou <img onerror> s'exécute dans le navigateur de tout visiteur — XSS stocké (persistant), particulièrement dangereux car il touche toutes les victimes sans interaction. Il faut encoder à la sortie selon le contexte : htmlspecialchars($c['body'], ENT_QUOTES, 'UTF-8'). L'injection de classe (option 2) est mineure. Il n'y a aucune requête SQL ici (option 3). Une CSP (option 4) est une défense en profondeur utile mais l'encodage de sortie est le correctif primaire.","tags":["xss","stored-xss","php","output-encoding"]},
  {"id":"scr-valeur-reflechie-dans-un-attribut","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Valeur réfléchie dans un attribut","company":"CWE-79 ; PHP htmlspecialchars — changement du défaut ENT_QUOTES en 8.1","language":"php","code":"$q = $_GET['q'];\necho \"<input type='text' value='\" . htmlspecialchars($q) . \"'>\";","question":"Ce code réfléchit une valeur de recherche dans un attribut HTML. Pourquoi reste-t-il vulnérable (PHP < 8.1) ?","options":["htmlspecialchars sans flag utilise ENT_COMPAT avant PHP 8.1 et n'échappe pas l'apostrophe, or l'attribut est en quotes simples","htmlspecialchars n'encode pas les entités HTML5 nommées, laissant passer des vecteurs comme &NewLine; dans l'attribut","le double encodage par défaut transforme les & déjà encodés, ce qui rouvre une injection dans le contexte attribut","le paramètre value étant réfléchi dans un contexte JavaScript, seul json_encode aurait neutralisé la charge utile"],"answer":0,"explanation":"Avant PHP 8.1, le flag par défaut de htmlspecialchars était ENT_COMPAT, qui échappe les guillemets doubles (\") mais PAS les apostrophes ('). Comme l'attribut value est délimité par des apostrophes, un q = ' onmouseover=alert(1) x=' s'échappe de l'attribut et injecte un gestionnaire d'événement : XSS réfléchi. Correctif : htmlspecialchars($q, ENT_QUOTES, 'UTF-8') (et idéalement délimiter les attributs par des guillemets doubles). Les entités HTML5 (option 2) et le double encodage (option 3) ne sont pas le mécanisme ici, et le contexte est bien un attribut HTML, pas du JS (option 4).","tags":["xss","php","htmlspecialchars","attribute-context"]},
  {"id":"scr-authentification-mongodb","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Authentification MongoDB","company":"CWE-943 ; OWASP — NoSQL Injection ; PortSwigger NoSQL injection","language":"javascript","code":"app.post('/login', async (req, res) => {\n  const user = await User.findOne({\n    username: req.body.username,\n    password: req.body.password\n  });\n  if (user) return res.json({ token: sign(user) });\n  res.status(401).end();\n});","question":"Cette route authentifie contre MongoDB via Mongoose. Quelle est la faille ?","options":["les valeurs du corps ne sont pas contraintes en chaînes : injection NoSQL avec {\"$ne\": null} contournant l'authentification","le mot de passe est comparé en clair dans la requête, ce qui présuppose un stockage non haché exploitable","findOne retourne le premier document correspondant, donc plusieurs comptes homonymes ouvrent une session arbitraire","sign(user) inclut l'objet utilisateur complet, exposant des champs sensibles dans le JWT retourné au client"],"answer":0,"explanation":"Si le corps est parsé en JSON, req.body.password peut être un OBJET, pas une chaîne. En envoyant {\"username\":\"admin\",\"password\":{\"$ne\":null}}, le filtre devient password: {$ne: null}, vrai pour tout mot de passe non nul : authentification contournée sans connaître le secret. Défense : forcer/valider le type (typeof === 'string'), un schéma strict, et ne jamais comparer le mot de passe en base — le vérifier avec bcrypt côté application. Le stockage en clair (option 2) est un autre défaut mais pas le vecteur d'injection. Les options 3 et 4 sont secondaires.","tags":["nosql-injection","mongodb","authentication-bypass","nodejs"]},
  {"id":"scr-procedure-stockee-dynamique","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Procédure stockée dynamique","company":"CWE-89 ; Microsoft Docs — EXECUTE vs sp_executesql ; OWASP SQLi Prevention","language":"sql","code":"CREATE PROCEDURE SearchUsers @name NVARCHAR(100)\nAS\nBEGIN\n    DECLARE @sql NVARCHAR(500);\n    SET @sql = 'SELECT id, email FROM Users WHERE name = ''' + @name + '''';\n    EXEC(@sql);\nEND","question":"Cette procédure T-SQL recherche des utilisateurs par nom. Où est la vulnérabilité ?","options":["@name est concaténé dans le SQL dynamique exécuté par EXEC : injection SQL, utiliser sp_executesql avec des paramètres","le fait d'être une procédure stockée n'immunise pas la requête, mais NVARCHAR(500) tronque et neutralise la charge","doubler les apostrophes à l'entrée suffirait à rendre la procédure sûre sans changer la construction du SQL","EXEC exécute la requête avec les droits du propriétaire de la procédure, ce qui n'expose que des lectures anodines"],"answer":0,"explanation":"Contrairement à une idée répandue, une procédure stockée n'est pas sûre en soi : ici @name est concaténé dans une chaîne SQL exécutée par EXEC. Une entrée comme `x''; DROP TABLE Users; --` (ou une clause UNION) est interprétée. La solution correcte est le SQL paramétré : EXEC sp_executesql N'SELECT id, email FROM Users WHERE name = @n', N'@n NVARCHAR(100)', @n = @name — les paramètres ne sont jamais concaténés. La troncation NVARCHAR (option 2) ne neutralise rien. Doubler les apostrophes (option 3) est fragile et échoue sur d'autres vecteurs. Les droits d'exécution (option 4) n'empêchent pas l'injection.","tags":["sql-injection","tsql","dynamic-sql","stored-procedure"]},
  {"id":"scr-generation-de-token-de-session","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Génération de token de session","company":"CWE-338 ; OWASP ASVS v4 §6.3 ; Java SecureRandom vs Random","language":"java","code":"import java.util.Random;\n\npublic String newSessionToken() {\n    Random rnd = new Random();\n    return Long.toHexString(rnd.nextLong());\n}","question":"Ce code génère un identifiant de session. Quelle est la faille cryptographique ?","options":["java.util.Random est un générateur linéaire prévisible : à partir de sorties observées, l'attaquant devine les tokens suivants","nextLong ne produit que 64 bits d'entropie, ce qui rend le token trivialement bruteforçable en quelques minutes","toHexString supprime les zéros de tête, créant des collisions entre tokens de longueurs différentes","un nouvel objet Random par appel ne réensemence pas la graine, réutilisant la même séquence pour tous les tokens"],"answer":0,"explanation":"java.util.Random est un PRNG à congruence linéaire (LCG) non cryptographique : sa graine fait 48 bits et son état est entièrement reconstructible après l'observation de quelques sorties consécutives, permettant de prédire les tokens passés et futurs — usurpation de session. Il faut java.security.SecureRandom (CSPRNG). Le problème n'est pas le nombre de bits en soi (option 2 : 64 bits résisteraient au bruteforce), ni les zéros de tête (option 3, mineur), ni la graine (option 4 : chaque new Random() prend justement une graine différente basée sur l'horloge, ce qui n'aide pas car reste prédictible).","tags":["insecure-randomness","java","securerandom","session-token"]},
  {"id":"scr-suppression-d-utilisateur-en-admin","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Suppression d'utilisateur en admin","company":"CWE-269 ; OWASP ASVS v4 §4.1 ; API Security Top 10 — Broken Function Level Authorization","language":"javascript","code":"app.post('/admin/delete-user', authenticate, async (req, res) => {\n  if (req.body.isAdmin) {\n    await User.destroy({ where: { id: req.body.userId } });\n    return res.json({ ok: true });\n  }\n  res.status(403).end();\n});","question":"Cet endpoint d'administration supprime un compte. Quelle est la faille de contrôle d'accès ?","options":["l'autorisation repose sur req.body.isAdmin fourni par le client : quiconque envoie isAdmin=true supprime des comptes","req.body.userId n'est pas typé, autorisant une injection d'opérateur qui supprime plusieurs utilisateurs à la fois","authenticate ne vérifie pas l'expiration du token, laissant un utilisateur déconnecté conserver ses privilèges","l'absence de confirmation CSRF permet de déclencher la suppression depuis une page tierce malveillante"],"answer":0,"explanation":"La décision d'autorisation lit isAdmin depuis le CORPS de la requête, entièrement contrôlé par le client : n'importe quel utilisateur authentifié envoie {\"isAdmin\":true,\"userId\":42} et supprime le compte de son choix — élévation de privilège / Broken Function Level Authorization. Le rôle doit être déterminé côté serveur à partir de l'identité authentifiée (req.user.role === 'admin' vérifié en base/claim signé). L'injection d'opérateur (option 2) dépendrait du typage mais n'est pas le défaut central ; l'expiration (option 3) et le CSRF (option 4) sont des points secondaires face à l'autorisation cassée.","tags":["privilege-escalation","access-control","nodejs","broken-authorization"]},
  {"id":"scr-allowlist-ssrf-par-sous-chaine","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Allowlist SSRF par sous-chaîne","company":"CWE-918 ; OWASP SSRF Prevention — flawed hostname validation","language":"python","code":"from urllib.parse import urlparse\nimport requests\n\ndef proxy(url):\n    host = urlparse(url).hostname or ''\n    if 'trusted.com' in host:\n        return requests.get(url, timeout=5).text\n    raise ValueError('blocked')","question":"Ce code veut n'autoriser que le domaine trusted.com. Pourquoi la protection est-elle contournable ?","options":["la vérification par sous-chaîne accepte trusted.com.evil.com ou evil-trusted.com : contournement de l'allowlist, SSRF","urlparse ne gère pas les URL sans schéma, renvoyant None pour hostname et provoquant une exception non gérée","requests suit les redirections par défaut : une page de trusted.com peut rediriger vers une cible interne arbitraire","le timeout de 5 secondes est insuffisant pour bloquer une attaque de type slowloris menée par le serveur cible"],"answer":0,"explanation":"'trusted.com' in host teste une SOUS-CHAINE, pas une correspondance de domaine. Un attaquant enregistre trusted.com.evil.com (le hostname CONTIENT bien la sous-chaîne mais le domaine effectif est evil.com) ou evil-trusted.com : la vérification passe et l'URL est récupérée côté serveur — SSRF. Il faut une comparaison exacte/suffixe contrôlé (host == 'trusted.com' or host.endswith('.trusted.com')). L'option 3 (redirections) est une VRAIE faiblesse complémentaire à corriger (allow_redirects=False), mais la faille primaire du code montré est la validation par sous-chaîne. Les options 2 et 4 ne sont pas des contournements d'allowlist.","tags":["ssrf","python","allowlist-bypass","url-validation"]},
  {"id":"scr-configuration-cors","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Configuration CORS","company":"CWE-942 ; PortSwigger — CORS vulnerabilities ; OWASP HTML5 Security","language":"javascript","code":"app.use((req, res, next) => {\n  res.header('Access-Control-Allow-Origin', req.headers.origin);\n  res.header('Access-Control-Allow-Credentials', 'true');\n  next();\n});","question":"Ce middleware configure CORS. Quelle est la vulnérabilité ?","options":["refléter l'Origin de la requête avec Allow-Credentials true : tout site lit les réponses authentifiées de la victime","utiliser un wildcard * pour Allow-Origin est requis avec les credentials, l'origine reflétée casse le préflight","l'en-tête Access-Control-Allow-Methods manquant empêche les requêtes non-GET et provoque un déni de service","répondre au préflight OPTIONS avec next() transmet la requête au routeur, exposant les routes internes"],"answer":0,"explanation":"Réfléchir aveuglément req.headers.origin dans Access-Control-Allow-Origin combiné à Allow-Credentials: true revient à faire confiance à TOUTE origine tout en autorisant l'envoi des cookies. Un site malveillant émet une requête cross-origin avec les credentials de la victime et LIT la réponse (données privées, tokens). Défense : allowlist stricte d'origines, ne refléter que si l'origine est autorisée, et éviter credentials avec des origines dynamiques. Le wildcard * est justement INTERDIT avec credentials (option 2 inversée). Les options 3 et 4 sont des considérations fonctionnelles, pas la faille de confiance d'origine.","tags":["cors","misconfiguration","nodejs","credentials"]},
  {"id":"scr-validation-de-redirection-par-prefixe","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Validation de redirection par préfixe","company":"CWE-601 ; PortSwigger — Open redirect ; regex anchoring pitfalls","language":"typescript","code":"function isAllowed(url: string): boolean {\n  return /^https:\\/\\/example\\.com/.test(url);\n}\n\nfunction redirect(res: Response, url: string) {\n  if (isAllowed(url)) res.redirect(url);\n  else res.redirect('/');\n}","question":"Cette fonction valide une URL de retour. Pourquoi est-elle contournable ?","options":["l'ancre de fin ($) manque : https://example.com.evil.com/ satisfait le préfixe et contourne la validation, open redirect","le point dans example.com n'est pas échappé, donc il matche n'importe quel caractère et élargit l'allowlist","sans le drapeau i, une URL en HTTPS majuscule passe la validation alors qu'elle vise un domaine non autorisé","test() conserve un état avec le drapeau global, renvoyant alternativement true et false sur des appels répétés"],"answer":0,"explanation":"La regex n'est ancrée qu'au DEBUT (^) : elle exige seulement que l'URL COMMENCE par https://example.com, sans borne de fin. Ainsi https://example.com.evil.com/path (domaine réel evil.com) et https://example.com@evil.com passent — open redirect. Valider avec un parseur d'URL et comparer host exactement (new URL(url).host === 'example.com'), pas par regex de préfixe. Le point EST échappé dans le motif (option 2 fausse). Les schémas https sont sensibles à la casse mais l'URL réelle serait en minuscules (option 3 marginale). La regex n'a pas de flag g (option 4).","tags":["open-redirect","regex","typescript","url-validation"]},
  {"id":"scr-extraction-d-archive-zip","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Extraction d'archive ZIP","company":"CWE-22 ; Snyk — Zip Slip vulnerability","language":"java","code":"ZipEntry entry;\nwhile ((entry = zis.getNextEntry()) != null) {\n    File out = new File(destDir, entry.getName());\n    try (FileOutputStream fos = new FileOutputStream(out)) {\n        byte[] buf = new byte[4096];\n        int n;\n        while ((n = zis.read(buf)) != -1) fos.write(buf, 0, n);\n    }\n}","question":"Ce code extrait une archive ZIP téléversée. Quelle est la vulnérabilité ?","options":["entry.getName() peut contenir ../ : Zip Slip écrivant hors de destDir, écrasement de fichiers arbitraires (RCE possible)","le flux zis n'est pas fermé entre les entrées, laissant des descripteurs ouverts jusqu'à épuisement des ressources","les entrées de type répertoire ne sont pas créées avant écriture, faisant échouer FileOutputStream sur un chemin profond","la taille décompressée n'est pas bornée : une archive zip bomb sature le disque et provoque un déni de service"],"answer":0,"explanation":"entry.getName() est contrôlé par l'auteur de l'archive et peut valoir ../../../etc/cron.d/x ou des antislash : new File(destDir, name) résout alors un chemin HORS de destDir — Zip Slip. Un attaquant écrase des fichiers sensibles (config, scripts, webshell) pouvant mener au RCE. Défense : canoniser la cible et vérifier target.getCanonicalPath().startsWith(destDir.getCanonicalPath() + File.separator) avant écriture. La zip bomb (option 4) est une autre menace réelle à limiter, mais la vulnérabilité montrée ici est le path traversal. Les options 2 et 3 sont des soucis fonctionnels/robustesse.","tags":["zip-slip","path-traversal","java","archive-extraction"]},
  {"id":"scr-ordre-chiffrement-mac-et-padding-oracle","type":"mcq","domain":"software","topic":"secure-review","difficulty":"senior","title":"Ordre chiffrement/MAC et padding oracle","company":"OWASP Cryptographic Storage Cheat Sheet ; Krawczyk 2001 — Encrypt-then-MAC ; padding oracle (Vaudenay)","question":"Pourquoi le schéma Encrypt-then-MAC prévient-il les attaques de type padding oracle sur AES-CBC, contrairement à MAC-then-Encrypt ?","options":["le MAC portant sur le chiffré est vérifié en premier : un chiffré altéré est rejeté avant tout déchiffrement, aucune info sur le padding ne fuit","le MAC-then-Encrypt chiffre aussi le MAC, ce qui empêche de le vérifier sans la clé et force un déchiffrement complet du padding","Encrypt-then-MAC utilise un IV authentifié qui rend le padding déterministe, supprimant la variabilité exploitée par l'oracle","les deux schémas sont équivalents face au padding oracle ; seule l'utilisation d'AES-GCM au lieu de CBC élimine réellement la faille"],"answer":0,"explanation":"Un padding oracle exploite le fait que le serveur DECHIFFRE puis distingue « padding invalide » de « padding valide ». En Encrypt-then-MAC, on vérifie d'abord le MAC calculé sur le chiffré (à temps constant) : tout chiffré falsifié par l'attaquant échoue au MAC et est rejeté SANS être déchiffré, donc aucun signal sur le padding n'est jamais émis. En MAC-then-Encrypt (et Encrypt-and-MAC), il faut déchiffrer avant de pouvoir vérifier, exposant l'oracle. Les schémas ne sont donc pas équivalents (option 4). L'option 2 décrit mal MtE, et l'option 3 invente un mécanisme d'IV inexistant. GCM est effectivement sûr, mais c'est précisément parce qu'il est un AEAD de type Encrypt-then-MAC.","tags":["cryptography","padding-oracle","encrypt-then-mac","cbc"]},
  {"id":"scr-token-de-reinitialisation-de-mot-de-pass","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Token de réinitialisation de mot de passe","company":"CWE-330 ; OWASP Forgot Password Cheat Sheet","language":"python","code":"import hashlib\n\ndef make_reset_token(user):\n    raw = str(user.id)\n    token = hashlib.sha256(raw.encode()).hexdigest()\n    save_token(user.id, token)\n    send_reset_link(user.email, token)\n    return token","question":"Ce code génère un token de réinitialisation. Quelle est la vulnérabilité ?","options":["le token est un hash déterministe de user.id : prévisible et constant, un attaquant le calcule pour n'importe quel compte","sha256 est trop rapide : le token peut être bruteforcé hors-ligne à partir de l'email de la victime en quelques heures","l'absence de date d'expiration laisse un token valide indéfiniment, ce qui est le principal risque exploitable ici","stocker le token en clair côté serveur permet une élévation de privilège en cas de fuite de la base de données"],"answer":0,"explanation":"Le token n'a AUCUNE part d'aléa : c'est simplement SHA-256(user.id). Comme les user.id sont souvent séquentiels/énumérables, l'attaquant calcule directement le token de n'importe quel compte (sha256 du nombre) et prend le contrôle via le lien de reset. Il faut un token aléatoire à forte entropie (secrets.token_urlsafe(32)) stocké haché, lié à un TTL court. L'expiration (option 3) et le stockage haché (option 4) sont de bonnes pratiques complémentaires, mais elles ne corrigent pas le défaut fondamental : la prévisibilité totale du token. sha256 « rapide » (option 2) n'est pas le problème puisqu'aucun bruteforce n'est même nécessaire.","tags":["insecure-randomness","password-reset","python","predictable-token"]},
  {"id":"scr-verification-de-mac-en-go","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Vérification de MAC en Go","company":"CWE-208 ; Go crypto/hmac — hmac.Equal documentation","language":"go","code":"func validMAC(message, messageMAC, key []byte) bool {\n    mac := hmac.New(sha256.New, key)\n    mac.Write(message)\n    expected := mac.Sum(nil)\n    return bytes.Equal(messageMAC, expected)\n}","question":"Cette fonction vérifie un HMAC. Quelle est la faille de sécurité ?","options":["bytes.Equal n'est pas à temps constant : fuite temporelle exploitable pour forger un MAC, utiliser hmac.Equal","mac.Sum(nil) réinitialise l'état du hachage, produisant un MAC vide comparé au messageMAC fourni","la clé n'est pas vérifiée en longueur : une clé plus courte que le bloc SHA-256 annule les garanties du HMAC","comparer messageMAC avant expected inverse les opérandes et retourne un faux positif sur des longueurs égales"],"answer":0,"explanation":"bytes.Equal s'arrête à la première divergence d'octet : son temps d'exécution dépend du préfixe commun, ce qui laisse fuiter, par mesure temporelle, combien d'octets de tête sont corrects — un attaquant reconstruit ainsi un MAC valide octet par octet (forge). La bibliothèque fournit hmac.Equal, à temps constant, précisément pour comparer des MAC. mac.Sum(nil) APPEND le digest à une slice vide et ne réinitialise pas l'état de façon problématique ici (option 2 fausse). HMAC gère les clés de toute longueur (option 3). L'ordre des opérandes de bytes.Equal n'affecte pas le résultat (option 4).","tags":["timing-attack","go","hmac","constant-time"]},
  {"id":"scr-cookie-de-session","type":"find-error","domain":"software","topic":"secure-review","difficulty":"intermediate","title":"Cookie de session","company":"CWE-1004 ; CWE-614 ; OWASP Session Management Cheat Sheet","language":"javascript","code":"res.cookie('session', sessionId, {\n  maxAge: 3600000\n});","question":"Ce code pose le cookie de session. Quelles protections manquent ?","options":["il manque httpOnly, secure et sameSite : vol via XSS (JS lit le cookie), transmission en clair et exposition au CSRF","maxAge est exprimé en secondes et non en millisecondes, ce qui expire la session prématurément côté client","le cookie n'est pas signé côté serveur, permettant à l'attaquant de forger un identifiant de session valide","l'attribut domain manque, ce qui restreint le cookie au sous-domaine courant et casse l'authentification unique"],"answer":0,"explanation":"Le cookie de session est posé sans les attributs de sécurité clés : sans httpOnly, un XSS lit document.cookie et vole la session ; sans secure, le cookie transite en clair sur HTTP (interception réseau) ; sans sameSite (Lax/Strict), il est envoyé lors de requêtes cross-site, facilitant le CSRF. Correct : res.cookie('session', id, { httpOnly:true, secure:true, sameSite:'lax', maxAge:3600000 }). maxAge est bien en millisecondes en Express (option 2 fausse). La signature (option 3) protège contre l'altération mais un ID de session opaque et aléatoire n'a pas besoin d'être « deviné » via signature ; ce n'est pas la lacune principale. domain (option 4) est un choix fonctionnel.","tags":["cookie-security","httponly","samesite","session"]},
  {"id":"scr-tri-dynamique-avec-l-orm","type":"find-error","domain":"software","topic":"secure-review","difficulty":"senior","title":"Tri dynamique avec l'ORM","company":"CWE-89 ; Sequelize — sequelize.literal escaping caveats","language":"javascript","code":"const { Op } = require('sequelize');\napp.get('/products', async (req, res) => {\n  const order = req.query.sort;\n  const rows = await Product.findAll({\n    order: sequelize.literal(order)\n  });\n  res.json(rows);\n});","question":"Ce code trie les résultats selon un paramètre de requête. Quelle est la vulnérabilité ?","options":["sequelize.literal insère la valeur brute sans échappement : injection SQL via sort dans la clause ORDER BY","order doit être passé sous forme de tableau [colonne, direction] et non de chaîne, sinon Sequelize l'ignore silencieusement","sequelize.literal est déprécié au profit de sequelize.col, qui seul applique l'échappement des identifiants","findAll sans clause limit charge toute la table, ce qui constitue le principal risque d'exploitation ici"],"answer":0,"explanation":"sequelize.literal injecte la chaîne TELLE QUELLE dans le SQL généré, en désactivant tout échappement — c'est son rôle documenté et son danger. Passer req.query.sort directement à literal permet une injection SQL via ORDER BY : `sort=(CASE WHEN (SELECT ...) THEN 1 ELSE 2 END)` ou des sous-requêtes exfiltrantes. Il faut une allowlist de colonnes/directions et utiliser la forme order: [['name','ASC']] validée. La forme tableau (option 2) est effectivement la bonne API mais Sequelize n'« ignore » pas une chaîne — il l'exécute via literal ici. literal n'est pas déprécié (option 3). L'absence de limit (option 4) est un souci de perf, pas la faille.","tags":["sql-injection","sequelize","orm","order-by"]},
  {"id":"scr-contournement-d-allowlist-ssrf-par-dns-r","type":"mcq","domain":"software","topic":"secure-review","difficulty":"senior","title":"Contournement d'allowlist SSRF par DNS rebinding","company":"CWE-918 ; OWASP SSRF Prevention — TOCTOU / DNS rebinding","question":"Un service valide qu'une URL résout vers une IP publique autorisée, puis fait la requête. Quelle attaque contourne cette défense et pourquoi ?","options":["DNS rebinding : entre la vérification et la requête, le domaine attaquant re-résout vers une IP interne (169.254.169.254), TOCTOU sur la résolution","encodage de l'IP en décimal ou hexadécimal dans l'URL : le validateur normalise l'IP mais le client HTTP la réinterprète différemment","injection d'un port non standard dans l'URL : la validation ne couvre que le port 80 et laisse passer les services internes sur d'autres ports","ajout d'un fragment @internal après le domaine autorisé : le client HTTP traite la partie après @ comme l'hôte réel de connexion"],"answer":0,"explanation":"Le défaut est un TOCTOU sur la résolution DNS : le validateur résout le domaine (obtient une IP publique autorisée), MAIS le client HTTP effectue sa PROPRE résolution un instant plus tard. Un attaquant contrôlant son DNS retourne d'abord l'IP publique (validation OK), puis, avec un TTL très court, l'IP interne (169.254.169.254, 127.0.0.1) au moment de la requête réelle : c'est le DNS rebinding. Défense : résoudre une seule fois et se connecter à cette IP validée (pin), refuser les plages privées/link-local après résolution. Les options 2, 3 et 4 décrivent d'autres vecteurs SSRF réels (formats d'IP, ports, confusion d'URL avec @) mais ne sont pas le contournement d'une allowlist qui a DEJA résolu et vérifié l'IP.","tags":["ssrf","dns-rebinding","toctou","cloud-metadata"]},
];
